public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns information about a basic group by its identifier. This is an offline method if the current user is not a bot
    /// </summary>
    public Task<TdLib.TdApi.Objects.BasicGroup> GetBasicGroupAsync(long basicGroupId = default)
    {

           using var activity =  StartCallActivity("GetBasicGroupAsync", typeof(GetBasicGroup).FullName ?? "GetBasicGroupAsync");

           try
           {
             return client.GetBasicGroupAsync(basicGroupId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
